import unittest

from importer.csv_parser import ParseError, parse_rows


class ParseRowsRaisesTest(unittest.TestCase):
    def test_missing_header(self):
        with self.assertRaisesRegex(ParseError, "header"):
            parse_rows("1,2,3\n")

    def test_parses_valid_file(self):
        try:
            rows = parse_rows("a,b\n1,2\n")
        except ParseError as err:  # surface a readable failure
            self.fail(f"unexpected parse error: {err}")
        self.assertEqual(rows, [{"a": "1", "b": "2"}])

